import{_ as t,o as n,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Wie passen bestehende ESPHome-Projekte zum Adapter?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/05.hintergrund/02.esphome-projekte.md"},"headers":[],"relativePath":"de/adapter/esphome/hintergrund/esphome-projekte.md","filePath":"de/adapter/esphome/hintergrund/esphome-projekte.md","lastUpdated":null}'),o={name:"de/adapter/esphome/hintergrund/esphome-projekte.md"};function d(i,e,s,p,m,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="wie-passen-bestehende-esphome-projekte-zum-adapter" tabindex="-1">Wie passen bestehende ESPHome-Projekte zum Adapter? <a class="header-anchor" href="#wie-passen-bestehende-esphome-projekte-zum-adapter" aria-label="Permalink to &quot;Wie passen bestehende ESPHome-Projekte zum Adapter?&quot;">​</a></h1><p><a id="custom-components-existing-esphome-projects"></a></p><h2 id="funktionieren-eigene-komponenten-und-bestehende-esphome-projekte-mit-dem-adapter" tabindex="-1">Funktionieren eigene Komponenten und bestehende ESPHome-Projekte mit dem Adapter? <a class="header-anchor" href="#funktionieren-eigene-komponenten-und-bestehende-esphome-projekte-mit-dem-adapter" aria-label="Permalink to &quot;Funktionieren eigene Komponenten und bestehende ESPHome-Projekte mit dem Adapter?&quot;">​</a></h2><p>Ja, solange die Firmware ihre Werte als Entitäten über die API meldet. Woher eine Entität kommt, ob aus ESPHome, einer externen Komponente oder einem fertigen Projekt, ist dem Adapter egal.</p><p>Der Adapter kennt diese Typen: Sensor, Binärsensor, Textsensor, Switch, Number, Text, Select, Button, Lock, Cover, Fan, Light und Climate. Meldet ein Gerät einen anderen Typ, steht einmal <code>DeviceType &lt;Typ&gt; not yet supported</code> mit den Details im Log, und für diesen Typ entstehen keine Werte.</p><p>Liefert eine Komponente einen JSON-Text, kommt er als ein Text-Datenpunkt an. Den zerlegst du im Skript mit <code>JSON.parse</code>. Vorhandene YAML-Dateien kannst du meist unverändert im Dashboard des Adapters nutzen.</p><p><a id="use-esphome-over-mqtt-instead"></a></p><h2 id="kann-ich-esphome-uber-mqtt-statt-oder-zusatzlich-zum-adapter-nutzen" tabindex="-1">Kann ich ESPHome über MQTT statt oder zusätzlich zum Adapter nutzen? <a class="header-anchor" href="#kann-ich-esphome-uber-mqtt-statt-oder-zusatzlich-zum-adapter-nutzen" aria-label="Permalink to &quot;Kann ich ESPHome über MQTT statt oder zusätzlich zum Adapter nutzen?&quot;">​</a></h2><p>Beides geht. Der Adapter nutzt nur die Native API, <code>api:</code> und <code>mqtt:</code> dürfen zusammen in der YAML stehen. Die MQTT-Werte kommen dann zusätzlich über einen MQTT-Adapter, meist als Text wie <code>ON</code> und <code>OFF</code>.</p><p>Nutzt du nur MQTT, brauchst du diesen Adapter nicht. Lass dann <code>api:</code> aus der YAML weg. Mit <code>api:</code> startet ein Gerät nach 15 Minuten ohne API-Verbindung neu, wenn du <code>reboot_timeout</code> nicht auf <code>0s</code> setzt.</p><p><a id="manage-bluetooth-proxy-adapter-dashboard"></a></p><h2 id="kann-ich-einen-bluetooth-proxy-mit-adapter-und-dashboard-verwalten" tabindex="-1">Kann ich einen Bluetooth-Proxy mit Adapter und Dashboard verwalten? <a class="header-anchor" href="#kann-ich-einen-bluetooth-proxy-mit-adapter-und-dashboard-verwalten" aria-label="Permalink to &quot;Kann ich einen Bluetooth-Proxy mit Adapter und Dashboard verwalten?&quot;">​</a></h2><p>Einen Bluetooth-Proxy fügst du im Adapter wie jedes Gerät hinzu. Der Adapter zeigt seine normalen Entitäten, z. B. Sensoren und Buttons. Die Proxy-Funktion selbst nutzt er nicht, sie ist für Home Assistant gedacht.</p><p>Ein fertig geflashter Proxy erscheint im Dashboard des Adapters mit „Adopt“, wenn das Dashboard ihn im Netz findet. Damit legt das Dashboard eine YAML an, und du verwaltest und aktualisierst ihn dort.</p>',14)])])}const l=t(o,[["render",d]]);export{c as __pageData,l as default};
